#include <bits/stdc++.h>
using namespace std;

int main(){
    long long HPY, ATKY, DEFY;
    long long HPM, ATKM, DEFM;
    long long h, a, d;
    cin >> HPY >> ATKY >> DEFY;
    cin >> HPM >> ATKM >> DEFM;
    cin >> h >> a >> d;

    long long best = LLONG_MAX;

    for (long long addATK = 0; addATK <= 200; addATK++){
        long long curATK = ATKY + addATK;
        if (curATK <= DEFM) continue;
        long long dmgToMonster = curATK - DEFM;
        long long turns = (HPM + dmgToMonster - 1) / dmgToMonster;

        for (long long addDEF = 0; addDEF <= 100; addDEF++){
            long long curDEF = DEFY + addDEF;
            long long dmgTaken = max(0LL, ATKM - curDEF);
            long long totalDamage = dmgTaken * turns;
            long long neededHP = totalDamage - HPY + 1;
            long long addHP = max(0LL, neededHP);

            long long cost = addHP * h + addATK * a + addDEF * d;
            if (cost < best) best = cost;
        }
    }

    cout << best << endl;
    return 0;
}
